package co.edu.uniquindio.brujula.identity.infrastructure.adapter.out.persistence;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.EnumType;
import jakarta.persistence.Enumerated;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import jakarta.persistence.Version;
import java.time.Instant;
import java.time.OffsetDateTime;
import java.util.UUID;

/**
 * JPA entity mapping to the {@code identity.app_user} table (created by Flyway V002, extended by
 * V008).
 *
 * <p>Uses UUID as primary key (matches the DB schema; generated by the domain factory). Optimistic
 * locking via {@code @Version} on the {@code version} column (DB-006).
 *
 * <p>V008 additions: consent_timestamp, terms_version, privacy_version, onboarding_state.
 */
@Entity
@Table(name = "app_user", schema = "identity")
class AppUserJpaEntity {

  @Id
  @Column(name = "id", nullable = false, updatable = false)
  private UUID id;

  @Column(name = "oidc_subject", unique = true, updatable = false)
  private String oidcSubject;

  @Column(name = "email", nullable = false, unique = true)
  private String email;

  @Column(name = "full_name", nullable = false)
  private String fullName;

  @Enumerated(EnumType.STRING)
  @Column(name = "role", nullable = false)
  private RoleJpa role;

  @Enumerated(EnumType.STRING)
  @Column(name = "status", nullable = false)
  private AccountStatusJpa status;

  @Column(name = "onboarding_completed", nullable = false)
  private boolean onboardingCompleted;

  @Version
  @Column(name = "version", nullable = false)
  private long version;

  @Column(name = "created_at", nullable = false, updatable = false)
  private OffsetDateTime createdAt;

  @Column(name = "updated_at")
  private OffsetDateTime updatedAt;

  // V008: consent evidence columns (nullable — OIDC-provisioned users have no consent record)
  @Column(name = "consent_timestamp")
  private Instant consentTimestamp;

  @Column(name = "terms_version")
  private String termsVersion;

  @Column(name = "privacy_version")
  private String privacyVersion;

  // V008: authoritative onboarding state (NOT NULL DEFAULT 'ACTIVE')
  @Column(name = "onboarding_state", nullable = false)
  private String onboardingState;

  // JPA requires a no-arg constructor
  protected AppUserJpaEntity() {}

  public AppUserJpaEntity(
      UUID id,
      String oidcSubject,
      String email,
      String fullName,
      RoleJpa role,
      AccountStatusJpa status,
      boolean onboardingCompleted,
      String onboardingState) {
    this.id = id;
    this.oidcSubject = oidcSubject;
    this.email = email;
    this.fullName = fullName;
    this.role = role;
    this.status = status;
    this.onboardingCompleted = onboardingCompleted;
    this.onboardingState = onboardingState;
    this.createdAt = OffsetDateTime.now();
    this.updatedAt = OffsetDateTime.now();
  }

  public UUID getId() {
    return id;
  }

  public String getOidcSubject() {
    return oidcSubject;
  }

  public String getEmail() {
    return email;
  }

  public String getFullName() {
    return fullName;
  }

  public RoleJpa getRole() {
    return role;
  }

  public AccountStatusJpa getStatus() {
    return status;
  }

  public boolean isOnboardingCompleted() {
    return onboardingCompleted;
  }

  public long getVersion() {
    return version;
  }

  public OffsetDateTime getCreatedAt() {
    return createdAt;
  }

  public OffsetDateTime getUpdatedAt() {
    return updatedAt;
  }

  public Instant getConsentTimestamp() {
    return consentTimestamp;
  }

  public void setConsentTimestamp(Instant consentTimestamp) {
    this.consentTimestamp = consentTimestamp;
  }

  public String getTermsVersion() {
    return termsVersion;
  }

  public void setTermsVersion(String termsVersion) {
    this.termsVersion = termsVersion;
  }

  public String getPrivacyVersion() {
    return privacyVersion;
  }

  public void setPrivacyVersion(String privacyVersion) {
    this.privacyVersion = privacyVersion;
  }

  public String getOnboardingState() {
    return onboardingState;
  }

  public void setOnboardingState(String onboardingState) {
    this.onboardingState = onboardingState;
  }

  // JPA enums stored as String to match VARCHAR CHECK constraints in the schema

  public enum RoleJpa {
    STUDENT,
    STAFF,
    ADMIN
  }

  public enum AccountStatusJpa {
    ACTIVE,
    INACTIVE,
    PENDING_VERIFICATION
  }
}
